"""B27 sheet definitions (Sora, Azure Sovereign, Astral Phoenix): name -> (sprite count, description). Prompts are generated from these so alternatives can be re-run (suffix @2 -> _v2)."""
PRE = ("Pixel-art game VFX in the chunky crisp pixel style of the reference image (visible pixels, hard edges, limited palette, no smooth airbrush gradients, no painterly blur). "
       "PURE BLACK background (#000000) everywhere, no ground plane, no character, no text, no frame, no border, no watermark. Original design. Additive-blend friendly: glows are bright shapes on black. "
       "Theme: AZURE SOVEREIGN, a precise celestial ranged-control power in deep NAVY, azure blue and electric cyan with white-blue highlights, crystalline facets and thin light lines. Palette strictly: navy, azure, cyan, white-blue highlight, no red, no orange, no gold, no green. ")
BIRD = "an original spectral ASTRAL PHOENIX (an elegant celestial bird of light, NOT a fox, NOT a dragon, NOT a serpent, NOT copied from any existing artwork): translucent blue-white radiant head with a sharp curved beak and a crest of feathers, smooth long neck, strong wings with clearly layered primary feathers, long elegant tail streamers, sharp talons"
def S(n, d): return (n, d)
SHEETS = {
 'concept': S(1, f"ONE single large sprite: {BIRD}, the whole bird in a regal pose seen from the side facing RIGHT with wings half raised, long neck arched, tail streamers flowing behind, translucent spectral look. Concept sheet for a fighter-wrapping aura."),
 'head_side': S(4, f"Each is ONLY the HEAD and long neck with crest of {BIRD} (no body, no wings) in profile facing RIGHT with the neck trailing left. Four variants: beak closed calm, beak half open, beak wide open crying out, lunging strike with a bright light-breath at the beak."),
 'head_front': S(4, f"Each is ONLY the HEAD and neck of {BIRD} (no body, no wings) seen from the FRONT, facing the viewer, symmetrical. Four variants: beak closed calm, beak open crying, glaring with crest raised, head tilted down striking."),
 'head_back': S(4, f"Each is ONLY the BACK of the head, crest and neck of {BIRD} (no body, no wings) seen from BEHIND, no face visible. Four variants of the same, crest feathers swaying differently."),
 'body': S(4, f"Each is a segment of the spectral body of {BIRD}, no head, no wings and no tail: variants 1) breast and neck feathers arching, 2) back plumage, 3) side flank feathers, 4) a folded body in a crouch. Translucent feather look, drawn to wrap around a standing person."),
 'wing_side': S(4, f"Each is the NEAR WING of {BIRD} seen from the side, attached at the shoulder at the RIGHT and sweeping LEFT: layered primary feathers fanned. Four loop frames of a wing beat: raised high, half sweep, full downstroke, folding back."),
 'wing_spread': S(4, f"Each is BOTH WINGS of {BIRD} seen from BEHIND, mirrored, spread to either side of a missing body (leave the centre empty, narrow), layered primary feathers. Four loop frames of a wing beat: raised, half open, fully spread, folded in."),
 'wing_cup': S(4, f"Each is TWO WINGS of {BIRD} cupping inward around an empty centre, like arms wrapping a sphere, seen from the front. Four frames: open wide, closing, cupped tight, thrust open outward."),
 'tail': S(4, f"Each is ONLY the long elegant TAIL STREAMERS of {BIRD}: five long flowing feather ribbons with bright tips rooted at the RIGHT and trailing LEFT in graceful curves. Four loop frames of a gentle sway."),
 'talon': S(4, f"Each is a pair of large TALONS and legs of {BIRD} striking DOWNWARD, claws splayed, seen slightly from above, feathers trailing. Four frames: raised, descending, impact with splayed claws, withdrawing."),
 'feather_blade': S(4, "Each is a single flying BLADE-FEATHER: a long thin crystalline feather shaped like a sword, pointing RIGHT, with a bright white-blue edge and a short trailing streak of light. Four variants: plain, with a cyan trail, with sparkles, large and bright."),
 'activation': S(4, f"Each is the materialisation of {BIRD} around a standing figure: a blue-white light burst of rising feathers, a spectral bird silhouette half formed inside a bright ring, wings unfolding. Four frames in sequence: feathers gathering, silhouette forming, wings spread burst, settle."),
 'dissolve': S(4, f"Each is {BIRD} dissolving into drifting blue feathers of light and sparkles, the shape breaking up from the tail towards the head. Four frames in sequence from mostly solid to almost only feathers."),
 'ground_ring': S(4, "Each is a flat GROUND RING seen in perspective as a wide squashed ellipse (3:1): a thin bright azure ring with fine crystalline tick marks and a few feathers of light, expanding. Four frames, ring growing bigger and thinner."),
 'prison_form': S(4, "Each is a crystalline PRISON LATTICE seen from above-front in perspective: tall faceted azure crystal spikes rising in a ring around an empty centre, linked by thin light lines. Four frames of formation: first small spikes, rising spikes, full lattice cage with glowing edges, cracks beginning to run through it."),
 'prison_shatter': S(4, "Each is a crystal PRISON SHATTERING: a ring of azure crystal shards bursting outward, pieces of faceted glass with bright edges and sparkles. Four frames in sequence: cracking, bursting, flying shards, fading sparkles."),
 'prison_shard': S(4, "Each is a single sharp flying CRYSTAL SHARD pointing RIGHT, faceted azure glass with a white edge and a short trail. Four variants of different size and shape."),
 'spear': S(4, "Each is a giant azure SPEAR OF LIGHT falling straight DOWN from above, seen from the side (point at the bottom): a long faceted crystalline shaft with a bright white tip and radiant streaks trailing upward. Four frames: forming high up, descending, near impact, fully driven in with flash."),
 'spear_impact': S(4, "Each is a small blue-white PILLAR IMPACT of a spear striking the ground: a column of light with a ring and crystalline shards bursting, seen from the front low angle. Four frames in sequence: flash, pillar, shards, fading."),
 'mark_sigil': S(4, "Each is a ground MARK SIGIL seen in perspective as a squashed ellipse (3:1): a thin azure circle with a small star and fine tick marks, glowing, shrinking and brightening. Four frames: faint large, medium, tight and bright, flash."),
 'collapse_vortex': S(4, "Each is a tiny BLACK-BLUE SINGULARITY: a dark core with luminous azure spiral arms and orbiting crystal fragments being drawn inward, seen from the front. Four frames of growing intensity: small, drawing in, large vortex, overloaded white-blue core."),
 'collapse_burst': S(4, "Each is an elegant expanding CRYSTALLINE DETONATION: a bright white-blue core with radiating faceted azure crystal rays and a ring, no fire. Four frames in sequence: ignition, full burst, expanding shards, dissipating."),
 'astral_orb': S(4, "Each is a rotating blue SPHERE of energy held between two hands (no hands drawn): a glossy azure ball with a bright core, orbiting bright particles and thin rotating rings. Four stages growing: small, medium, large, overcharged with a double ring."),
 'orb_trail': S(4, "Each is a projectile TRAIL streaking to the LEFT behind a fast blue energy sphere: a thick azure comet streak with a white-blue core, spiral ripples and sparkles. Four variants of increasing length."),
 'astral_burst': S(4, "Each is a heavy AZURE BLAST: a bright white-blue core with a double layer of expanding azure shock rings and crystalline rays. Four frames in sequence: ignition, full double-layer blast, spreading, dissipating."),
 'astral_ring': S(4, "Each is a thin delayed PRESSURE RING, a perfect circle seen straight-on with azure distortion bands and sparkles, expanding. Four frames growing thinner."),
 'flight_wings': S(4, "Each is a pair of WING-SHAPED JET BURSTS of azure light streaming DOWN and BACK from the bottom of a flying figure: two fanned feather-like plumes of light with sparkles. Four loop frames."),
 'flight_ring': S(4, "Each is a FEATHER-RING shockwave: a ring of azure pressure containing small feather marks, seen in perspective as a squashed ellipse, expanding. Four frames."),
 'wisps': S(4, "Each is a small body-bound feather WISP: a short curling plume of blue-white light about the size of a person forearm, tapered, flickering, with a bright core and few sparkles. Four animation frames of the same wisp, rising."),
 'wisp_arc': S(4, "Each is a tiny thin azure ENERGY ARC wrapping like a ribbon around a forearm: a curved thin bright band with a few sparkles. Four animation frames."),
 'icons': S(6, "Each is a square game ICON on black in a bold readable pixel style with a thick bright outline, one per skill, in order left to right and top to bottom: 1) a ring of crystal spikes (prison), 2) a falling giant spear of light (heavens spear), 3) a swirling dark-blue singularity with inward arrows (collapse), 4) a glowing blue sphere between two small hands (devastation), 5) a blue-white phoenix head (overdrive), 6) a flying crystal blade-feather (astral blades)."),
}
def prompt(name):
    n, d = SHEETS[name]
    lay = "Sheet with exactly ONE sprite, centred." if n == 1 else ("Sheet with exactly SIX separate sprites in a grid, evenly spaced, separated by wide black gaps." if n == 6 else "Sheet with exactly FOUR separate sprites in one row, evenly spaced, separated by wide black gaps (no sprite touching another or the sheet edge).")
    return PRE + lay + " " + d
